  splash=array();std::set<ActorKey> seen;if(!null(direct))seen.insert(key(direct));
  if(!ricochet){require(isArray(m.get("splash"))&&rows(m.get("splash")).size()<=30,"invalid splash batch");require(record.wire.get("is_he").truth()||rows(m.get("splash")).empty(),"AP projectile has splash targets");for(const auto&r:rows(m.get("splash"))){Value effect=validateEffect(r,record.wire,true,sender);require(seen.insert(key(effect)).second,"duplicate projectile victim");splash.array.push_back(std::move(effect));}}
